parse_works = function(data, demographics){
  uids = demographics |&gt; distinct(uid) |&gt; pull() |&gt; na.omit()
  works = list()
  for (id in uids){
    work = data$works[[id]] 

    if (is_tibble(work) & ("work_id" %in% colnames(work))) {
      work = work |&gt; distinct(work_id, .keep_all = TRUE)
    }

    works[[id]] = work
  }
  return(works)
}

add_uid_to_authorships = function(works) {
  # create a lookup table
  lookup = works |&gt; 
    bind_rows() |&gt; distinct(uid, author_id) |&gt; drop_na()

  # add uid
  for (id_ in names(works)){
    tab = works[[id_]]
    if (any(nrow(tab) == 0, !is_tibble(tab))) next

    works[[id_]] = tab |&gt;
      mutate(
        authorships = map(authorships,
          ~ .x |&gt; mutate(
              id = str_remove(id, "^https://openalex.org/")
            )
        ),
        authorships = map(authorships,
          ~ lookup |&gt; 
            right_join(.x, by = join_by(author_id == id))  
        )
      )
  }
  return(works)
}



Parse Scholar information

parse_scholars = function(data, demographics){
  uids = demographics |&gt; distinct(uid) |&gt; pull() |&gt; na.omit()
  scholartab = data[['id']] |&gt; bind_rows() 

  authors= list()
  for (id_ in uids){
    authors[[id_]] = scholartab |&gt; filter(uid == id_)
  }

  return(authors)
