Implementation Nationalize.io
nationalize_name() — fetch nationality probabilities for names with persistent caching
Reads an existing cache of name→nationality results (data/utils/origin_cache.Rds), queries only uncached search_name values via the nationalize.io API, merges new results with the cache, de-duplicates, and writes the updated cache back to disk. Live API calls are performed only when a boolean flag eval_ok is TRUE; otherwise the function simply returns the current cache.
How it works: - Loads .env with dotenv::load_dot_env() and reads the API key from Sys.getenv("GENDERIZE_API_KEY") (the Nationalize/Genderize/Agify services share the same key format). - Filters out names already present in origin_cache$name. - For remaining names (if eval_ok is TRUE), calls nationalize(name, sliced = FALSE, apikey = APIKEY, simplify = FALSE) and collects responses. - Binds new rows with the cache and keeps distinct rows (distinct(.keep_all = TRUE)). - Drops a top-level country column if present (some client returns a nested/list column).

nationalize_name = function(idx) {
  origin_cache = readRDS(file.path('data', '_cache', "origin_cache.Rds"))

  # load api key from secrets file
  dotenv::load_dot_env()
  APIKEY &lt;- Sys.getenv("GENDERIZE_API_KEY")

  # select uncached names
  idx =  idx |&gt; filter(!search_name %in% origin_cache$name)

  # select last_names
  last_names = idx$search_name |&gt; na.omit() |&gt; unique() |&gt; sort()
  # last_names = last_names[12:22]

  # fetch nationality results
  hold = c()
  if (-eval_ok) {
    for (name in last_names){
      resp = nationalize(name, sliced=FALSE, apikey = APIKEY, simplify = FALSE)
      hold[[name]] = resp 
    }
  }

  # combine cache with results and put new cache results
  origin = bind_rows(origin_cache, bind_rows(hold)) |&gt; 
    distinct(.keep_all = TRUE)

  if ("country" %in% colnames(origin)) origin = origin |&gt; select(-country)

  saveRDS(origin, file.path('data', '_cache', "origin_cache.Rds"))

  return(origin)
}

